// Log-linear models: stats' loglin (iterative proportional fitting) and MASS's loglm (its formula front end) with
// anova and residuals. Behaviour: oracle/tobit-betareg-loglin-behaviour.md (clean room: from the documentation and
// the output of R; no source of R or of a package was read). Written for rStats.js.
import { pchisq } from "../distributions/chisq.js";
import { parseFormula, termsOf } from "./formula.js";
import type { DataFrame } from "./modelFrame.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const LOGLIN_KEYS = ["start", "eps", "iter"] as const;
const LOGLM_KEYS = ["start", "eps", "iter", "levels"] as const;
const LOGLM_RESIDUALS_KEYS = ["type"] as const;
// Generated by `node scripts/option-keys.mjs --write` (end)

/**
 * A contingency table of any number of dimensions: `counts` in R's order (the first index varies fastest), `dim`
 * the number of levels of each dimension, and optionally the names of the dimensions and of their levels.
 * @category Regression
 */
export interface ArrayTable {
  /** The counts, the first index varying fastest. */
  counts: readonly number[];
  /** The number of levels of each dimension. */
  dim: readonly number[];
  /** Names of the dimensions. */
  names?: readonly string[];
  /** Names of the levels of each dimension. */
  levels?: readonly (readonly string[])[];
}

/**
 * A table as nested arrays, the first index outermost (`t[i][j][k]`).
 * @category Regression
 */
export type NestedTable = readonly (number | NestedTable)[];

interface Table { counts: number[]; dim: number[]; names: string[] | undefined; levels: string[][] | undefined }

function toTable(t: ArrayTable | NestedTable): Table {
  if (Array.isArray(t)) {
    const dim: number[] = [];
    let cur: unknown = t;
    while (Array.isArray(cur)) { dim.push(cur.length); cur = cur[0]; }
    const counts = new Array<number>(dim.reduce((a, b) => a * b, 1));
    const strides = dim.map((_, j) => dim.slice(0, j).reduce((a, b) => a * b, 1));
    const walk = (node: unknown, depth: number, offset: number): void => {
      if (depth === dim.length) { counts[offset] = Number(node); return; }
      if (!Array.isArray(node) || node.length !== dim[depth]) throw new RangeError("the nested arrays must form a rectangular table");
      node.forEach((child, i) => walk(child, depth + 1, offset + i * strides[depth]!));
    };
    walk(t, 0, 0);
    return { counts, dim, names: undefined, levels: undefined };
  }
  const a = t as ArrayTable;
  const size = a.dim.reduce((x, y) => x * y, 1);
  if (a.counts.length !== size) throw new RangeError("the length of 'counts' must be the product of 'dim'");
  if (a.names !== undefined && a.names.length !== a.dim.length) throw new RangeError("'names' must have one name per dimension");
  return { counts: Array.from(a.counts), dim: Array.from(a.dim), names: a.names?.slice(), levels: a.levels?.map((l) => l.slice()) };
}

/** Sums of `x` (R's order, dims `dim`) over the dimensions not in `keep` (0-based, in the order given). */
function marginSums(x: readonly number[], dim: readonly number[], keep: readonly number[]): number[] {
  const outDim = keep.map((k) => dim[k]!);
  const out = new Array<number>(outDim.reduce((a, b) => a * b, 1)).fill(0);
  const idx = new Array<number>(dim.length).fill(0);
  for (let c = 0; c < x.length; c++) {
    let o = 0, s = 1;
    for (let j = 0; j < keep.length; j++) { o += idx[keep[j]!]! * s; s *= outDim[j]!; }
    out[o]! += x[c]!;
    for (let j = 0; j < dim.length; j++) { if (++idx[j]! < dim[j]!) break; idx[j] = 0; }
  }
  return out;
}

/** Index of each cell in the margin `keep`. */
function marginIndex(dim: readonly number[], keep: readonly number[]): number[] {
  const out: number[] = [], idx = new Array<number>(dim.length).fill(0), size = dim.reduce((a, b) => a * b, 1);
  for (let c = 0; c < size; c++) {
    let o = 0, s = 1;
    for (const k of keep) { o += idx[k]! * s; s *= dim[k]!; }
    out.push(o);
    for (let j = 0; j < dim.length; j++) { if (++idx[j]! < dim[j]!) break; idx[j] = 0; }
  }
  return out;
}

interface IpfResult { fit: number[]; iterations: number; deviation: number; converged: boolean }

function ipf(counts: number[], dim: number[], margins: number[][], start: number[], eps: number, iter: number): IpfResult {
  // the start is first scaled to the table's total (R: counts of 1e-300 converge in one cycle, log 27)
  const total = counts.reduce((a, b) => a + b, 0), s0 = start.reduce((a, b) => a + b, 0);
  let fit = start.map((v) => (v / s0) * total);
  if (margins.length === 0) return { fit, iterations: 0, deviation: NaN, converged: true };
  const obs = margins.map((m) => marginSums(counts, dim, m)), index = margins.map((m) => marginIndex(dim, m));
  let it = 0, deviation = 0;
  // a cycle adjusts each margin in turn; its deviation is the largest |observed - fitted| margin difference seen just
  // before the adjustments (so a model fitted in one cycle reports two)
  while (it < iter) {
    it++;
    deviation = 0;
    margins.forEach((m, k) => {
      const cur = marginSums(fit, dim, m), o = obs[k]!;
      for (let j = 0; j < cur.length; j++) deviation = Math.max(deviation, Math.abs(o[j]! - cur[j]!));
      const ratio = cur.map((c, j) => (c === 0 ? 0 : o[j]! / c));
      fit = fit.map((v, c) => v * ratio[index[k]![c]!]!);
    });
    if (deviation < eps) return { fit, iterations: it, deviation, converged: true };
  }
  return { fit, iterations: it, deviation, converged: false };
}

/** All non-empty subsets of the margins (the terms of the hierarchical model), by size, then by dimensions. */
function modelTerms(margins: number[][]): number[][] {
  const seen = new Map<string, number[]>();
  for (const m of margins) {
    const s = [...m].sort((a, b) => a - b);
    for (let mask = 1; mask < 1 << s.length; mask++) {
      const t = s.filter((_, j) => mask & (1 << j));
      seen.set(t.join(","), t);
    }
  }
  return [...seen.values()].sort((a, b) => a.length - b.length || compareColex(a, b));
}
// R's order of the terms of a size: by the last dimension, then the one before (P.Q, Q.R, P.S, R.S)
const compareColex = (a: number[], b: number[]): number => { for (let j = a.length - 1; j >= 0; j--) if (a[j] !== b[j]) return a[j]! - b[j]!; return 0; };

/** The zero-sum parameters of log(fit): for each term, the alternating sum of the marginal means of log(fit). */
function parameters(fit: number[], dim: number[], terms: number[][], dimNames: string[]): Record<string, number[]> {
  // a fitted zero (a structural zero) makes every parameter NA in R
  const lf = fit.some((v) => !(v > 0)) ? fit.map(() => NaN) : fit.map(Math.log), size = fit.length;
  const means = (keep: number[]): number[] => {
    const cells = keep.reduce((a, k) => a * dim[k]!, 1);
    return marginSums(lf, dim, keep).map((v) => v / (size / cells));
  };
  const out: Record<string, number[]> = { "(Intercept)": [lf.reduce((a, b) => a + b, 0) / size] };
  for (const t of terms) {
    const outDim = t.map((k) => dim[k]!), cells = outDim.reduce((a, b) => a * b, 1);
    const eff = new Array<number>(cells).fill(0);
    for (let mask = 0; mask < 1 << t.length; mask++) {
      const sub = t.filter((_, j) => mask & (1 << j)), sign = (t.length - sub.length) % 2 === 0 ? 1 : -1;
      const m = means(sub), subPos = sub.map((k) => t.indexOf(k));
      const idx = new Array<number>(t.length).fill(0);
      for (let c = 0; c < cells; c++) {
        let o = 0, s = 1;
        for (let j = 0; j < sub.length; j++) { o += idx[subPos[j]!]! * s; s *= dim[sub[j]!]!; }
        eff[c]! += sign * m[o]!;
        for (let j = 0; j < t.length; j++) { if (++idx[j]! < outDim[j]!) break; idx[j] = 0; }
      }
    }
    out[t.map((k) => dimNames[k]).join(".")] = eff;
  }
  return out;
}

// The cells of the statistics are those with a positive start (a structural zero is left out even when its count is
// not 0; a sampling zero fitted as 0 makes Pearson's statistic NaN, as R). (o - f) ((o - f) / f) keeps counts near
// 1e300 from overflowing (R's statistics are NaN there)
function statistics(counts: number[], fit: number[], start: number[]): { lrt: number; pearson: number } {
  let lrt = 0, pearson = 0;
  counts.forEach((o, c) => {
    if (!(start[c]! > 0)) return;
    const f = fit[c]!;
    pearson += (o - f) * ((o - f) / f);
    if (o > 0) lrt += o * (Math.log(o) - Math.log(f));
  });
  return { lrt: 2 * lrt, pearson };
}

/**
 * Options for {@link loglin}.
 * @category Regression
 */
export interface LoglinOptions {
  /** Starting table (R's order, default all 1); zeros mark structural zeros, kept zero in the fit. */
  start?: readonly number[];
  /** Convergence bound on the largest absolute difference between observed and fitted margins (default 0.1). */
  eps?: number;
  /** Maximum number of iterations (default 20). */
  iter?: number;
}

/**
 * Result of {@link loglin}.
 * @category Regression
 */
export interface LoglinResult {
  /** Likelihood-ratio and Pearson statistics, and their degrees of freedom (no adjustment for structural zeros). */
  lrt: number;
  /** Pearson's statistic. */
  pearson: number;
  /** Degrees of freedom. */
  df: number;
  /** The margins fitted, with names where the table has them. */
  margin: (string | number)[][];
  /** The fitted table (R's order). */
  fit: number[];
  /**
   * Zero-sum parameters of log(fit): "(Intercept)", one entry per term ("A", "A.B"), each in R's order; all NaN when
   * a fitted value is 0 (as R's NA).
   */
  param: Record<string, number[]>;
  /** The names of `param` in R's order (an object puts names that are numbers first). */
  paramNames: string[];
  /** Iterations (as R prints them). */
  iterations: number;
  /** The deviation of the last iteration (NaN without margins). */
  deviation: number;
  /** Warnings. */
  warnings: string[];
}

function resolveMargin(m: readonly (string | number)[] | string | number, t: Table): number[] {
  const parts = Array.isArray(m) ? m : [m as string | number];
  return parts.map((v) => {
    const k = typeof v === "number" ? v - 1 : t.names?.indexOf(v) ?? -1;
    if (!Number.isInteger(k) || k < 0 || k >= t.dim.length) throw new RangeError("'margin' must contain names or numbers corresponding to 'table'");
    return k;
  });
}

function fitLoglin(t: Table, margins: number[][], start: number[], eps: number, iter: number): LoglinResult {
  if (!(eps > 0)) throw new RangeError("'eps' must be positive");
  // (R errors for iter = 0: "incorrect specification of 'table' or 'start'")
  if (!Number.isInteger(iter) || iter < 1) throw new RangeError("'iter' must be a positive integer");
  const r = ipf(t.counts, t.dim, margins, start, eps, iter);
  const dimNames = t.dim.map((_, k) => t.names?.[k] ?? String(k + 1));
  const terms = modelTerms(margins);
  const cells = t.counts.length;
  const df = cells - 1 - terms.reduce((a, term) => a + term.reduce((p, k) => p * (t.dim[k]! - 1), 1), 0);
  const { lrt, pearson } = statistics(t.counts, r.fit, start);
  return {
    lrt, pearson, df, margin: margins.map((m) => m.map((k) => t.names?.[k] ?? k + 1)), fit: r.fit,
    param: parameters(r.fit, t.dim, terms, dimNames), paramNames: ["(Intercept)", ...terms.map((term) => term.map((k) => dimNames[k]).join("."))], iterations: r.iterations, deviation: r.deviation,
    warnings: r.converged ? [] : ["algorithm did not converge"],
  };
}

/**
 * Fits a hierarchical log-linear model to a contingency table by iterative proportional fitting (Haberman 1972),
 * given the margins to fit (the maximal terms, e.g. `[["A", "B"], ["A", "C"]]` for [AB][AC]). Margins are names of
 * dimensions or 1-based numbers, as in R. Equivalent to R's `loglin()`. It returns the fit and
 * the parameters (R's `fit = TRUE, param = TRUE`).
 *
 * The iterations stop when the largest absolute difference between observed and fitted margins falls below `eps`
 * (0.1 by default, a loose bound, as R) or after `iter` cycles.
 * @example
 * ```ts
 * const t = { counts: [10, 20, 30, 40], dim: [2, 2], names: ["A", "B"] };
 * loglin(t, [["A"], ["B"]]).lrt; // 0.80435 (the independence model)
 * ```
 * @category Regression
 */
export function loglin(table: ArrayTable | NestedTable, margin: readonly (readonly (string | number)[] | string | number)[], options: LoglinOptions = {}): LoglinResult {
  checkOptions(options, LOGLIN_KEYS, "loglin"); // generated: option-keys.mjs
  const t = toTable(table);
  if (t.counts.some((v) => !(v >= 0))) throw new RangeError("the counts must be non-negative numbers");
  const start = options.start === undefined ? t.counts.map(() => 1) : Array.from(options.start);
  if (start.length !== t.counts.length) throw new RangeError("'start' and 'table' must be same length");
  const margins = margin.map((m) => resolveMargin(m, t));
  return fitLoglin(t, margins, start, options.eps ?? 0.1, options.iter ?? 20);
}

/**
 * Options for {@link loglm}.
 * @category Regression
 */
export interface LoglmOptions {
  /** Starting table (R's order of the table), zeros for structural zeros; with a table `data` only. */
  start?: readonly number[];
  /** Convergence bound (default 0.1), passed to {@link loglin}. */
  eps?: number;
  /** Maximum number of iterations (default 40). */
  iter?: number;
  /** The order of the levels of factors of a data frame (default: sorted). */
  levels?: Record<string, readonly string[]>;
}

/**
 * Result of {@link loglm}.
 * @category Regression
 */
export interface LoglmResult extends LoglinResult {
  /** The formula. */
  formula: string;
  /** The likelihood-ratio statistic (the deviance against the saturated model). */
  deviance: number;
  /** The table fitted: counts (R's order), dims, names and levels. */
  frequencies: LoglmFrequencies;
  /** Cells of the table. */
  nobs: number;
}

/**
 * The table of a {@link loglm} fit.
 * @category Regression
 */
export interface LoglmFrequencies {
  /** The counts (R's order). */
  counts: number[];
  /** The number of levels of each dimension. */
  dim: number[];
  /** Names of the dimensions. */
  names: string[];
  /** Names of the levels. */
  levels: string[][];
}

/**
 * Log-linear model given by a formula: a front end to {@link loglin}. The right-hand side gives the margins (its
 * maximal terms; `a:b`, `a*b` and `a/b` are the same margin). `data` is a table with named dimensions (numbers in
 * the formula stand for dimensions), or a data frame with the frequencies on the left of the formula, where cells
 * absent from the data are structural zeros and each takes one degree of freedom off. Equivalent to R's
 * `MASS::loglm()`.
 * @example
 * ```ts
 * const t = { counts: [10, 20, 30, 40, 12, 18, 25, 35], dim: [2, 2, 2], names: ["A", "B", "C"] };
 * loglm("~ A*B + C", t).deviance; // 0.54958
 * ```
 * @category Regression
 */
export function loglm(formula: string, data: ArrayTable | NestedTable | DataFrame, options: LoglmOptions = {}): LoglmResult {
  checkOptions(options, LOGLM_KEYS, "loglm"); // generated: option-keys.mjs
  const isTable = Array.isArray(data) || (typeof (data as ArrayTable).dim === "object" && Array.isArray((data as ArrayTable).counts));
  // numbers in the formula stand for dimensions: they become names .v1, .v2, ...
  // (not the power of ^2)
  const f = formula.replace(/(?<!\^\s*)(?<![A-Za-z0-9._])(\d+)(?![A-Za-z0-9._])/g, (_, d: string) => `.v${d}`);
  const parsed = parseFormula(f);
  let t: Table, start: number[], structural = 0;
  if (isTable) {
    t = toTable(data as ArrayTable | NestedTable);
    const names = t.dim.map((_, k) => t.names?.[k] ?? `.v${k + 1}`);
    t.names = t.names === undefined ? names : t.names.slice();
    t.levels = t.levels ?? t.dim.map((n) => Array.from({ length: n }, (_, i) => String(i + 1)));
    start = options.start === undefined ? t.counts.map(() => 1) : Array.from(options.start);
    if (start.length !== t.counts.length) throw new RangeError("'start' and 'table' must be same length");
  } else {
    if (parsed.response === undefined) throw new TypeError("a data frame needs the frequencies on the left of the formula");
    const df = data as DataFrame;
    const terms0 = termsOf(parsed, Object.keys(df));
    const vars = terms0.variables.slice(1);
    const freq = df[parsed.response];
    if (freq === undefined) throw new RangeError(`object '${parsed.response}' not found`);
    const n = freq.length;
    const levels = vars.map((v) => {
      const col = df[v];
      if (col === undefined) throw new RangeError(`object '${v}' not found`);
      const given = options.levels?.[v];
      return given !== undefined ? Array.from(given) : [...new Set(Array.from(col, (x) => String(x)))].sort();
    });
    const dim = levels.map((l) => l.length), size = dim.reduce((a, b) => a * b, 1);
    const counts = new Array<number>(size).fill(0), present = new Array<boolean>(size).fill(false);
    for (let i = 0; i < n; i++) {
      let o = 0, s = 1;
      vars.forEach((v, j) => { const lv = levels[j]!.indexOf(String(df[v]![i])); if (lv < 0) throw new RangeError(`level of ${v} not in 'levels'`); o += lv * s; s *= dim[j]!; });
      counts[o]! += Number(freq[i]); present[o] = true;
    }
    structural = present.filter((p) => !p).length;
    start = present.map((p) => (p ? 1 : 0));
    t = { counts, dim, names: vars, levels };
  }
  const terms = termsOf(parsed, t.names!);
  const vars = terms.variables.slice(terms.response === -1 ? 0 : 1);
  // the maximal terms, in the order of the terms
  const sets = terms.terms.map((term) => term.map((v) => terms.variables[v]!));
  const maximal = sets.filter((s, i) => !sets.some((o, j) => j !== i && o.length > s.length && s.every((v) => o.includes(v))));
  // a name, or .vk for the k-th dimension
  const dimOf = (v: string): number => {
    const byNumber = /^\.v(\d+)$/.exec(v);
    const k = byNumber !== null && !t.names!.includes(v) ? Number(byNumber[1]) - 1 : t.names!.indexOf(v);
    if (k < 0 || k >= t.dim.length) throw new RangeError(`'${v}' is not a dimension of the table`);
    return k;
  };
  vars.forEach(dimOf);
  const margins = maximal.map((s) => s.map(dimOf));
  const r = fitLoglin(t, margins, start, options.eps ?? 0.1, options.iter ?? 40);
  const names = t.names!.map((nm) => nm);
  return {
    ...r, df: r.df - structural, formula, deviance: r.lrt,
    frequencies: { counts: t.counts, dim: t.dim, names, levels: t.levels! }, nobs: t.counts.length,
  };
}

/**
 * Options for {@link loglmResiduals}.
 * @category Regression
 */
export interface LoglmResidualsOptions {
  /** `"deviance"` (default), `"pearson"` or `"response"`. */
  type?: "deviance" | "pearson" | "response";
}

/**
 * Residuals of a {@link loglm} fit, one per cell (R's order). Equivalent to `MASS::residuals.loglm()` in R.
 * @example
 * ```ts
 * const t = { counts: [10, 20, 30, 40], dim: [2, 2], names: ["A", "B"] };
 * loglmResiduals(loglm("~ A + B", t), { type: "pearson" }); // [-0.57735, 0.4714, 0.37796, -0.30861]
 * ```
 * @category Regression
 */
export function loglmResiduals(fit: LoglmResult, options: LoglmResidualsOptions = {}): number[] {
  checkOptions(options, LOGLM_RESIDUALS_KEYS, "loglmResiduals"); // generated: option-keys.mjs
  const type = options.type ?? "deviance";
  if (type !== "deviance" && type !== "pearson" && type !== "response") throw new RangeError("'arg' should be one of “deviance”, “pearson”, “response”");
  return fit.frequencies.counts.map((o, c) => {
    const f = fit.fit[c]!;
    if (type === "response") return o - f;
    if (type === "pearson") return (o - f) / Math.sqrt(f);
    return Math.sign(o - f) * Math.sqrt(2 * Math.abs((o > 0 ? o * Math.log(o / f) : 0) - (o - f)));
  });
}

/**
 * Result of {@link loglmAnova}: the models in the order given, then the saturated model.
 * @category Regression
 */
export interface LoglmAnovaResult {
  /** "Model 1", ..., "Saturated". */
  rows: string[];
  /** The formulas ("" for the saturated model). */
  formulas: string[];
  /** Deviances. */
  deviance: number[];
  /** Residual degrees of freedom. */
  df: number[];
  /**
   * Changes from the previous row (NaN for the first), and the chi-squared p-values of the changes, computed as R's
   * `1 - pchisq()` (a p-value below about 1e-16 is 0).
   */
  deltaDeviance: number[];
  /** Changes of the degrees of freedom. */
  deltaDf: number[];
  /** p-values. */
  p: number[];
}

/**
 * Likelihood-ratio tests between nested {@link loglm} fits and of the last against the saturated model. Equivalent
 * to `MASS::anova.loglm()` in R.
 * @example
 * ```ts
 * const t = { counts: [10, 20, 30, 40, 12, 18, 25, 35], dim: [2, 2, 2], names: ["A", "B", "C"] };
 * loglmAnova(loglm("~ A + B + C", t), loglm("~ A*B + C", t)).p; // [NaN, 0.46019, 0.90787]
 * ```
 * @category Regression
 */
export function loglmAnova(...fits: LoglmResult[]): LoglmAnovaResult {
  if (fits.length < 1) throw new RangeError("give at least one fit");
  const deviance = [...fits.map((f) => f.deviance), 0], df = [...fits.map((f) => f.df), 0];
  const deltaDeviance = deviance.map((d, i) => (i === 0 ? NaN : deviance[i - 1]! - d));
  const deltaDf = df.map((d, i) => (i === 0 ? NaN : df[i - 1]! - d));
  return {
    rows: [...fits.map((_, i) => `Model ${i + 1}`), "Saturated"], formulas: [...fits.map((f) => f.formula), ""],
    // R computes 1 - pchisq(...): p-values below about 1e-16 are 0 and small ones lose digits (2.8967876430918693e-7
    // where the upper tail is 2.896787643364249e-7). Kept as R (demo example loglm-anova, log 26)
    deviance, df, deltaDeviance, deltaDf, p: deltaDeviance.map((d, i) => (i === 0 ? NaN : 1 - (pchisq(d, deltaDf[i]!) as number))),
  };
}
